#[derive(Debug, Clone, PartialEq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum NumpyObject {
    Int(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    ComplexArray(Vec<(f64, f64)>), // each tuple is (real, imag)
    Str(String),
    Bool(bool),
    Generic,
}

pub fn obj2sctype(
    rep: NumpyObject,
    default: Option<NumpyScalarType>,
) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Int(_) => Some(NumpyScalarType::Int64),
        NumpyObject::Float(_) => Some(NumpyScalarType::Float64),
        NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        NumpyObject::ComplexArray(_) => Some(NumpyScalarType::Complex128),
        NumpyObject::Str(_) => Some(NumpyScalarType::String),
        NumpyObject::Bool(_) => Some(NumpyScalarType::Bool),
        NumpyObject::Generic => default,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_obj2sctype_primitives() {
        assert_eq!(
            obj2sctype(NumpyObject::Int(42), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Float(3.14), None),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Bool(true), None),
            Some(NumpyScalarType::Bool)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Str("hi".into()), None),
            Some(NumpyScalarType::String)
        );
    }

    #[test]
    fn test_obj2sctype_arrays() {
        assert_eq!(
            obj2sctype(NumpyObject::IntArray(vec![1, 2, 3]), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::FloatArray(vec![1.0, 2.0]), None),
            Some(NumpyScalarType::Float64)
        );
        let ca = vec![(0.0, 1.0), (2.0, 3.0)];
        assert_eq!(
            obj2sctype(NumpyObject::ComplexArray(ca), None),
            Some(NumpyScalarType::Complex128)
        );
    }

    #[test]
    fn test_obj2sctype_generic_with_default() {
        assert_eq!(
            obj2sctype(NumpyObject::Generic, Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Float64)
        );
    }

    #[test]
    fn test_obj2sctype_generic_without_default() {
        assert_eq!(obj2sctype(NumpyObject::Generic, None), None);
    }
}